/* ====== 全局：字体修改 ====== */
@import url("字体链接");

body,
textArea,
pre,
code,
.edit_textarea {
    font-family: "字体名称" !important;
    font-weight: normal;
}

/* ====== 🌊【附加内容放置区】 ====== */
/* PS：附加的功能在这里 删除 或者 修改 */

/* 🌊 附加功能 */
:root {
    /* ▶ 正则 限宽 */
    /* （不需要时，删除，或者改为100%） */
    --regex_width: 85%;

    /* ▶ 气泡 毛玻璃 效果 */
    /* （越大越模糊，为0不模糊，推荐5px~10px） */
    --blur: 0px;

    /* ▶ 引用文本 高亮 */
    /* （越大越深，0%无高亮效果，建议设置为10~30%） */
    --opacity: 0%;

    /* ▶ 大代码块 内容限高 */
    /* （不需要时，删除，或者改为很大数） */
    --code_block_max_height: 240px;

    /* ▶ 推理块 内容限高 */
    /* （不需要时，删除，或者改为很大数） */
    --reasoning_max_height: 500px;

    /* ▶ QR栏（快捷回复） 内容限高 */
    /* （不需要时，删除，或者改为很大数） */
    --qr_max_height: 10em;
}

/* 🌊 消息文字 */
.mes_text p {
    /* ▶ 段落首行缩进 */
    /* （设置为2em，即可首行缩进两字符） */
    text-indent: 0em;

    /* ▶ 内行距 (行与行) */
    line-height: 1.6em;
    /* ▶ 外行距 (段与段) */
    margin-bottom: 1em;

    /* ▶ 字体加粗 */
    /* （越大越粗，常规400，粗体700） */
    font-weight: 400;
    /* ▶ 字体大小 */
    /* （越高越大，默认1em） */
    font-size: 1em;
}

/* 🌊 全局文字 */
:root {
    /* ▶ 全局文字加粗 */
    /* （默认为0不加粗，建议设为0~0.5） */
    -webkit-text-stroke-width: 0px !important;
}

